"use strict";(function(){let showSpinner=!1;window.onbeforeunload=function(){if(!showSpinner)return;document.querySelector("body").classList.add("rpb-reloading");let div=document.createElement("div");div.id="rpb-reloading";div.innerHTML='<span class="loader"></span>';document.body.appendChild(div);setTimeout(()=>{div.classList.add("show")},10)};window.addEventListener("click",(e)=>{let button=e.target.closest(".ui-dialog-buttonset button");if(!button)return;showSpinner=!0})})();function _RockSortable(){}
_RockSortable.prototype.getContainer=function(el){return el.closest("[sortable]")||!1};_RockSortable.prototype.getPageId=function(el){let id=el.getAttribute("data-rpbblock");if(id)return id;return el.querySelector("[data-rpbblock]").getAttribute("data-rpbblock")};_RockSortable.prototype.getPageIds=function(el){let container=this.getContainer(el);let blocks=container.querySelectorAll("[data-rpbblock]");let ids=[];blocks.forEach((block)=>{ids.push(this.getPageId(block))});return ids};_RockSortable.prototype.saveSort=function(el){let url=RockFrontend.rootUrl+"rockpagebuilder-savesort?block="+this.getPageId(el)+"&sort="+this.getPageIds(el).join("|");fetch(url).then((response)=>{if(response.ok){return response.json()}
throw new Error("Something went wrong")}).then((responseJson)=>{}).catch((error)=>{console.error(error)})};var RockSortable=new _RockSortable();function makeSortable(){let containers=document.querySelectorAll("[sortable]");let body=document.querySelector("body");containers.forEach((container)=>{if(container.hasAttribute("data-sortable"))return;container.setAttribute("data-sortable",!0);new Sortable(container,{animation:150,filter:".no-sortable",onChoose:(e)=>{body.classList.add("no-alfred")},onEnd:(e)=>{body.classList.remove("no-alfred");RockSortable.saveSort(e.item)},onUnchoose:(e)=>{body.classList.remove("no-alfred")},})})}
document.addEventListener("DOMContentLoaded",makeSortable)